ALTER TABLE public.recovery_journey ADD COLUMN IF NOT EXISTS current_streak integer NOT NULL DEFAULT 0; CREATE TABLE IF NOT EXISTS public.failure_debriefs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, journey_id uuid REFERENCES public.recovery_journey(id) ON DELETE SET NULL, mood text, trigger_description text, what_happened text, lesson_learned text, action_plan text, ai_suggestions jsonb, created_at timestamp with time zone NOT NULL DEFAULT now(), updated_at timestamp with time zone NOT NULL DEFAULT now() ); ALTER TABLE public.failure_debriefs ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users can view own debriefs" ON public.failure_debriefs FOR SELECT TO authenticated USING (auth.uid() = user_id); CREATE POLICY "Users can insert own debriefs" ON public.failure_debriefs FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id); CREATE POLICY "Users can update own debriefs" ON public.failure_debriefs FOR UPDATE TO authenticated USING (auth.uid() = user_id); ALTER TABLE public.trigger_logs ADD COLUMN IF NOT EXISTS location_context text;